pm.test("Status code é 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Deve validar estrutura de livros e paginação", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("books");
    pm.expect(response).to.have.property("pagination");

    pm.expect(response.books).to.be.an("array");

    pm.expect(response.pagination.total).to.be.a("number");
    pm.expect(response.pagination.limit).to.eql(20);
    pm.expect(response.pagination.currentPage).to.eql(1);
});

pm.test("Status code é 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Deve validar os dados do livro", function () {
    const response = pm.response.json();
    const book = response.book;

    pm.expect(book.id).to.eql(27);
    pm.expect(book.title).to.eql("Fragmentos Sobre um Tempo Programado");
    pm.expect(book.author).to.eql("Everson Almeida");
    pm.expect(book.category).to.eql("Ficção Científica");
});

pm.test("Deve validar disponibilidade do livro", function () {
    const response = pm.response.json();

    pm.expect(response.availability.isAvailable).to.eql(true);
    pm.expect(response.availability.available_copies).to.eql(1);
    pm.expect(response.availability.reserved_copies).to.eql(7);
});

pm.test("Status code é 404", function () {
    pm.response.to.have.status(404);
});
pm.test("Dever retornar a mensagem", function () {
    pm.expect(pm.response.text()).to.include("Livro não encontrado.");
});

pm.test("Status code é 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Deve validar mensagem de sucesso", function () {
    const response = pm.response.json();

    pm.expect(response.message)
        .to.eql("Livro criado com sucesso.");
});

pm.test("Deve validar os dados do livro cadastrado", function () {
    const response = pm.response.json();
    const book = response.book;

    pm.expect(book).to.have.property("id");
    pm.expect(book.title).to.eql("Fragmentos Sobre um Tempo Programado");
    pm.expect(book.author).to.eql("Everson Almeida");
    pm.expect(book.category).to.eql("Ficção Científica");
    pm.expect(book.total_copies).to.eql(8);
});

pm.test("Status code é 400", function () {
    pm.response.to.have.status(400);
});
pm.test("Deve validar mensagem de campo obrigatório", function () {
    const response = pm.response.json();

    pm.expect(response.message)
        .to.include("title");

    pm.expect(response.field).to.eql("title");
});

pm.test("Status code é 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Deve validar atualização do livro", function () {
    const response = pm.response.json();

    pm.expect(response.message)
        .to.eql("Livro atualizado com sucesso.");

    pm.expect(response.bookId).to.eql(24);

    pm.expect(response.updatedFields).to.include("total_copies");
    pm.expect(response.updatedFields).to.include("available_copies");
    pm.expect(response.updatedFields).to.include("category");

    pm.expect(response.previousTitle)
        .to.eql("Admirável Mundo Novo");
});

pm.test("Status code é 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Deve validar os dados do livro excluído", function () {
    const response = pm.response.json();

    pm.expect(response.deletedBook.id).to.eql(23);
    pm.expect(response.deletedBook.title).to.eql("Hub de Leitura");
    pm.expect(response.deletedBook.author).to.eql("Autor Exemplo");
});
